1	/**
2	 * Seed sensible per-game pricing tiers (GamePlan rows).
3	 *
4	 * For each tier we pick:
5	 *   - basePlanId   = the smallest active VPS Plan whose ramMB >= the tier's ramMB
6	 *                    (falls back to the largest plan if none is big enough).
7	 *   - osTemplateId = that game's OsTemplate (family=<game>, category=APPLICATION),
8	 *                    if one exists; otherwise null (deploy resolves it at runtime).
9	 *
10	 * Idempotent: dedupes by (gameFamily, name) and upserts.
11	 *
12	 * Run: cd /opt/nxeon && npx tsx prisma/seed-gameplans.ts
13	 */
14	import { PrismaClient } from "@prisma/client";
15	
16	const db = new PrismaClient();
17	
18	type TierSpec = {
19	  gameFamily: string;
20	  name: string;
21	  ramMB: number;
22	  cpuCores: number;
23	  diskGB: number;
24	  slots: number;
25	  priceCents: number;
26	  featured?: boolean;
27	};
28	
29	// Retail prices in cents, monthly term. RAM/slots/price differ per game.
30	const TIERS: TierSpec[] = [
31	  // Minecraft — light, scales by player count.
32	  { gameFamily: "minecraft", name: "Minecraft — 2 GB / 10 slots", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 10, priceCents: 499 },
33	  { gameFamily: "minecraft", name: "Minecraft — 4 GB / 20 slots", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 899, featured: true },
34	  { gameFamily: "minecraft", name: "Minecraft — 8 GB / 50 slots", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 50, priceCents: 1599 },
35	
36	  // Valheim — RAM-hungry world simulation.
37	  { gameFamily: "valheim", name: "Valheim — 4 GB / 10 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 10, priceCents: 999 },
38	  { gameFamily: "valheim", name: "Valheim — 8 GB / 20 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 20, priceCents: 1699, featured: true },
39	
40	  // Rust — needs the most RAM & CPU, big populations.
41	  { gameFamily: "rust", name: "Rust — 4 GB / 40 slots", ramMB: 4096, cpuCores: 2, diskGB: 40, slots: 40, priceCents: 1299 },
42	  { gameFamily: "rust", name: "Rust — 6 GB / 60 slots", ramMB: 6144, cpuCores: 3, diskGB: 60, slots: 60, priceCents: 1799, featured: true },
43	  { gameFamily: "rust", name: "Rust — 10 GB / 150 slots", ramMB: 10240, cpuCores: 4, diskGB: 80, slots: 150, priceCents: 2999 },
44	
45	  // Palworld — heavy, small-ish parties.
46	  { gameFamily: "palworld", name: "Palworld — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 8, priceCents: 1499 },
47	  { gameFamily: "palworld", name: "Palworld — 16 GB / 32 players", ramMB: 16384, cpuCores: 4, diskGB: 80, slots: 32, priceCents: 2799, featured: true },
48	
49	  // CS2 — competitive FPS, modest RAM.
50	  { gameFamily: "cs2", name: "CS2 — 2 GB / 12 slots", ramMB: 2048, cpuCores: 2, diskGB: 40, slots: 12, priceCents: 699 },
51	  { gameFamily: "cs2", name: "CS2 — 4 GB / 24 slots", ramMB: 4096, cpuCores: 3, diskGB: 50, slots: 24, priceCents: 1199, featured: true },
52	
53	  // Terraria — lightweight sandbox.
54	  { gameFamily: "terraria", name: "Terraria — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 20, slots: 8, priceCents: 449 },
55	  { gameFamily: "terraria", name: "Terraria — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 16, priceCents: 799, featured: true },
56	];
57	
58	async function main() {
59	  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
60	  if (plans.length === 0) {
61	    throw new Error("No active VPS plans found — run the main seed first (npx prisma db seed).");
62	  }
63	  const largest = plans[plans.length - 1];
64	
65	  // Cache the first game image per family.
66	  const imageByFamily = new Map<string, string>();
67	  for (const spec of TIERS) {
68	    if (imageByFamily.has(spec.gameFamily)) continue;
69	    const os = await db.osTemplate.findFirst({
70	      where: { family: spec.gameFamily, category: "APPLICATION" },
71	      orderBy: { sortOrder: "asc" },
72	    });
73	    imageByFamily.set(spec.gameFamily, os?.id ?? "");
74	  }
75	
76	  let created = 0;
77	  let updated = 0;
78	  let sortByGame = new Map<string, number>();
79	
80	  for (const spec of TIERS) {
81	    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
82	    const osId = imageByFamily.get(spec.gameFamily) || null;
83	    const sortOrder = (sortByGame.get(spec.gameFamily) ?? 0);
84	    sortByGame.set(spec.gameFamily, sortOrder + 1);
85	
86	    const data = {
87	      gameFamily: spec.gameFamily,
88	      name: spec.name,
89	      ramMB: spec.ramMB,
90	      cpuCores: spec.cpuCores,
91	      diskGB: spec.diskGB,
92	      slots: spec.slots,
93	      priceCents: spec.priceCents,
94	      termMonths: 1,
95	      basePlanId: basePlan.id,
96	      osTemplateId: osId,
97	      featured: spec.featured ?? false,
98	      active: true,
99	      sortOrder,
100	    };
101	
102	    // Dedupe by (gameFamily, name) — no DB unique constraint exists on the pair.
103	    const existing = await db.gamePlan.findFirst({
104	      where: { gameFamily: spec.gameFamily, name: spec.name },
105	    });
106	    if (existing) {
107	      await db.gamePlan.update({ where: { id: existing.id }, data });
108	      updated++;
109	    } else {
110	      await db.gamePlan.create({ data });
111	      created++;
112	    }
113	    console.log(
114	      `  ${spec.gameFamily.padEnd(10)} ${spec.name.padEnd(32)} → base=${basePlan.name} img=${osId ? "yes" : "auto"}`,
115	    );
116	  }
117	
118	  const total = await db.gamePlan.count();
119	  console.log(`\nGamePlans seeded: ${created} created, ${updated} updated. Total in DB: ${total}.`);
120	}
121	
122	main()
123	  .catch((e) => {
124	    console.error(e);
125	    process.exit(1);
126	  })
127	  .finally(async () => {
128	    await db.$disconnect();
129	  });
130

1	import { SignJWT, jwtVerify } from "jose";
2	import { cookies } from "next/headers";
3	import { cache } from "react";
4	import { db } from "./db";
5	import type { User } from "@prisma/client";
6	
7	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
8	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
9	
10	export async function createSession(userId: string) {
11	  const token = await new SignJWT({ sub: userId })
12	    .setProtectedHeader({ alg: "HS256" })
13	    .setIssuedAt()
14	    .setExpirationTime("7d")
15	    .sign(secret);
16	  const jar = await cookies();
17	  jar.set(COOKIE, token, {
18	    httpOnly: true,
19	    sameSite: "lax",
20	    secure: process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1",
21	    maxAge: 60 * 60 * 24 * 7,
22	    path: "/",
23	  });
24	}
25	
26	export async function destroySession() {
27	  const jar = await cookies();
28	  jar.delete(COOKIE);
29	}
30	
31	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
32	
33	/** The real signed-in account, ignoring any impersonation. */
34	export const realUser = cache(async (): Promise<User | null> => {
35	  const jar = await cookies();
36	  const token = jar.get(COOKIE)?.value;
37	  if (!token) return null;
38	  try {
39	    const { payload } = await jwtVerify(token, secret);
40	    if (!payload.sub) return null;
41	    const user = await db.user.findUnique({ where: { id: payload.sub } });
42	    if (!user || user.suspended) return null;
43	    return user;
44	  } catch {
45	    return null;
46	  }
47	});
48	
49	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
50	export const currentUser = cache(async (): Promise<User | null> => {
51	  const real = await realUser();
52	  if (!real) return null;
53	  if (real.role === "ADMIN") {
54	    const jar = await cookies();
55	    const imp = jar.get(IMP_COOKIE)?.value;
56	    if (imp) {
57	      try {
58	        const { payload } = await jwtVerify(imp, secret);
59	        if (payload.adminId === real.id && typeof payload.sub === "string") {
60	          const target = await db.user.findUnique({ where: { id: payload.sub } });
61	          if (target) return target;
62	        }
63	      } catch {
64	        /* expired/invalid impersonation — fall through to real user */
65	      }
66	    }
67	  }
68	  return real;
69	});
70	
71	/** Non-null when the current request is an admin impersonating a customer. */
72	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
73	  const real = await realUser();
74	  if (!real || real.role !== "ADMIN") return null;
75	  const target = await currentUser();
76	  if (!target || target.id === real.id) return null;
77	  return { admin: real, target };
78	});
79	
80	export async function setImpersonation(targetUserId: string) {
81	  const real = await realUser();
82	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
83	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id })
84	    .setProtectedHeader({ alg: "HS256" })
85	    .setIssuedAt()
86	    .setExpirationTime("2h")
87	    .sign(secret);
88	  const jar = await cookies();
89	  jar.set(IMP_COOKIE, token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: 7200 });
90	}
91	
92	export async function clearImpersonation() {
93	  const jar = await cookies();
94	  jar.delete(IMP_COOKIE);
95	}
96	
97	export async function requireUser(): Promise<User> {
98	  const user = await currentUser();
99	  if (!user) throw new Error("UNAUTHORIZED");
100	  return user;
101	}
102	
103	export async function requireAdmin(): Promise<User> {
104	  const user = await requireUser();
105	  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
106	  return user;
107	}
108	
109	/**
110	 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
111	 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
112	 * per-area gating lives in lib/rbac.ts (`requireArea`).
113	 */
114	export async function requireStaff(): Promise<User> {
115	  const user = await realUser();
116	  if (!user) throw new Error("UNAUTHORIZED");
117	  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
118	    throw new Error("FORBIDDEN");
119	  }
120	  return user;
121	}
