1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { revalidatePath } from "next/cache";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { requireArea } from "./rbac";
9	import { debitWallet, InsufficientBalanceError } from "./wallet";
10	import { addMonths } from "./billing-terms";
11	import { GAME_FAMILIES, type GameFamily } from "./games";
12	
13	/**
14	 * Game servers as a distinct product. A `GamePlan` is one pricing tier for one
15	 * game (Minecraft 2 GB / 10 slots, etc). Admins (billing area) manage the
16	 * catalogue; customers order a tier, which provisions a VM sized by the tier's
17	 * base VPS Plan running the game's OsTemplate image.
18	 *
19	 * This module owns:
20	 *   - adminSaveGamePlan / adminToggleGamePlan / adminDeleteGamePlan (CRUD)
21	 *   - orderGameServer (customer deploy) — mirrors lib/actions.ts orderServer.
22	 */
23	
24	type Result = { error?: string; ok?: boolean };
25	
26	// ---------- Admin CRUD ----------
27	
28	const planSchema = z.object({
29	  id: z.string().optional(),
30	  gameFamily: z.enum(GAME_FAMILIES),
31	  name: z.string().min(2).max(80),
32	  ramMB: z.coerce.number().int().min(256).max(262144),
33	  cpuCores: z.coerce.number().int().min(1).max(64),
34	  diskGB: z.coerce.number().int().min(1).max(4096),
35	  slots: z.coerce.number().int().min(1).max(100000).optional(),
36	  priceCents: z.coerce.number().int().min(0).max(100000000),
37	  termMonths: z.coerce.number().int().min(1).max(36),
38	  basePlanId: z.string().min(1),
39	  osTemplateId: z.string().optional(),
40	  sortOrder: z.coerce.number().int().min(0).max(100000),
41	});
42	
43	/**
44	 * Create or update a GamePlan tier. ADMIN/BILLING only, audit-logged. Validates
45	 * the chosen base VPS Plan (sizing source) and the game OsTemplate (must belong
46	 * to the same game family, if provided).
47	 */
48	export async function adminSaveGamePlan(prev: Result | undefined, formData: FormData): Promise<Result> {
49	  const admin = await requireArea("billing");
50	
51	  const rawSlots = String(formData.get("slots") ?? "").trim();
52	  const rawOs = String(formData.get("osTemplateId") ?? "").trim();
53	  const parsed = planSchema.safeParse({
54	    id: formData.get("id") || undefined,
55	    gameFamily: formData.get("gameFamily"),
56	    name: formData.get("name"),
57	    ramMB: formData.get("ramMB"),
58	    cpuCores: formData.get("cpuCores"),
59	    diskGB: formData.get("diskGB"),
60	    slots: rawSlots === "" ? undefined : rawSlots,
61	    priceCents: formData.get("priceCents"),
62	    termMonths: formData.get("termMonths"),
63	    basePlanId: formData.get("basePlanId"),
64	    osTemplateId: rawOs === "" ? undefined : rawOs,
65	    sortOrder: formData.get("sortOrder") ?? 0,
66	  });
67	  if (!parsed.success) {
68	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
69	  }
70	  const d = parsed.data;
71	
72	  const base = await db.plan.findUnique({ where: { id: d.basePlanId } });
73	  if (!base) return { error: "Choose a valid base VPS plan for provisioning." };
74	
75	  let osTemplateId: string | null = null;
76	  if (d.osTemplateId) {
77	    const os = await db.osTemplate.findUnique({ where: { id: d.osTemplateId } });
78	    if (!os) return { error: "Selected game image not found." };
79	    if (os.family !== d.gameFamily) {
80	      return { error: `That image belongs to "${os.family}", not "${d.gameFamily}".` };
81	    }
82	    osTemplateId = os.id;
83	  }
84	
85	  const featured = formData.get("featured") === "on";
86	  const active = formData.get("active") === "on";
87	
88	  const data = {
89	    gameFamily: d.gameFamily,
90	    name: d.name.trim(),
91	    ramMB: d.ramMB,
92	    cpuCores: d.cpuCores,
93	    diskGB: d.diskGB,
94	    slots: d.slots ?? null,
95	    priceCents: d.priceCents,
96	    termMonths: d.termMonths,
97	    basePlanId: d.basePlanId,
98	    osTemplateId,
99	    featured,
100	    active,
101	    sortOrder: d.sortOrder,
102	  };
103	
104	  if (d.id) {
105	    const existing = await db.gamePlan.findUnique({ where: { id: d.id } });
106	    if (!existing) return { error: "Tier not found." };
107	    await db.gamePlan.update({ where: { id: d.id }, data });
108	  } else {
109	    await db.gamePlan.create({ data });
110	  }
111	
112	  await db.auditLog.create({
113	    data: {
114	      userId: admin.id,
115	      action: d.id ? "gameplan.update" : "gameplan.create",
116	      detail: `${data.gameFamily} — ${data.name} (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
117	    },
118	  });
119	  revalidatePath("/admin/game-plans");
120	  return { ok: true };
121	}
122	
123	/** Flip a tier's active flag. */
124	export async function adminToggleGamePlan(id: string): Promise<void> {
125	  const admin = await requireArea("billing");
126	  const gp = await db.gamePlan.findUnique({ where: { id } });
127	  if (!gp) return;
128	  await db.gamePlan.update({ where: { id }, data: { active: !gp.active } });
129	  await db.auditLog.create({
130	    data: { userId: admin.id, action: "gameplan.toggle", detail: `${gp.name} → active=${!gp.active}` },
131	  });
132	  revalidatePath("/admin/game-plans");
133	}
134	
135	/** Delete a tier. Refused while servers reference it. */
136	export async function adminDeleteGamePlan(id: string): Promise<Result> {
137	  const admin = await requireArea("billing");
138	  const gp = await db.gamePlan.findUnique({
139	    where: { id },
140	    include: { _count: { select: { servers: true } } },
141	  });
142	  if (!gp) return { error: "Tier not found." };
143	  if (gp._count.servers > 0) {
144	    return { error: `Can't delete — ${gp._count.servers} server(s) use this tier. Disable it instead.` };
145	  }
146	  await db.gamePlan.delete({ where: { id } });
147	  await db.auditLog.create({
148	    data: { userId: admin.id, action: "gameplan.delete", detail: `${gp.gameFamily} — ${gp.name}` },
149	  });
150	  revalidatePath("/admin/game-plans");
151	  return { ok: true };
152	}
153	
154	// ---------- Customer deploy ----------
155	
156	/** Short random suffix so auto-generated hostnames don't collide. */
157	function rand(n = 6): string {
158	  return Math.random().toString(36).slice(2, 2 + n);
159	}
160	
161	/**
162	 * Order a game server from a GamePlan tier. Mirrors lib/actions.ts orderServer:
163	 * validate the tier, atomically debit the wallet for `gamePlan.priceCents`, then
164	 * create the Server (sized by the tier's base VPS plan, running the game image)
165	 * plus a PROVISION Job in one transaction. Redirects to the new server.
166	 */
167	export async function orderGameServer(gamePlanId: string): Promise<Result> {
168	  const user = await requireUser();
169	
170	  const gp = await db.gamePlan.findUnique({
171	    where: { id: gamePlanId },
172	    include: { basePlan: true },
173	  });
174	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
175	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
176	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
177	    return { error: "Unknown game family." };
178	  }
179	
180	  // Resolve the game image: the tier's own OsTemplate, else any active image for
181	  // this game family. A game server can't provision without an image.
182	  let osTemplateId = gp.osTemplateId;
183	  if (osTemplateId) {
184	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
185	    if (!os?.active) osTemplateId = null;
186	  }
187	  if (!osTemplateId) {
188	    const os = await db.osTemplate.findFirst({
189	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
190	      orderBy: { sortOrder: "asc" },
191	    });
192	    if (!os) return { error: "No game image is configured for this game yet." };
193	    osTemplateId = os.id;
194	  }
195	
196	  const chargeCents = gp.priceCents;
197	  if (user.balanceCents < chargeCents) {
198	    return { error: "Insufficient balance. Top up your wallet first." };
199	  }
200	
201	  const hostname = `${gp.gameFamily}-${rand()}`;
202	
203	  let server;
204	  try {
205	    server = await db.$transaction(async (tx) => {
206	      await debitWallet(tx, user.id, chargeCents);
207	      await tx.walletTransaction.create({
208	        data: {
209	          userId: user.id,
210	          amountCents: -chargeCents,
211	          description: `Game server: ${gp.name} (${gp.gameFamily})`,
212	        },
213	      });
214	      const s = await tx.server.create({
215	        data: {
216	          name: hostname,
217	          hostname,
218	          userId: user.id,
219	          planId: gp.basePlanId,
220	          gamePlanId: gp.id,
221	          osTemplateId: osTemplateId!,
222	          termMonths: gp.termMonths,
223	          wantsDedicatedIp: false,
224	          expiresAt: addMonths(new Date(), gp.termMonths),
225	        },
226	      });
227	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
228	      return s;
229	    });
230	  } catch (e) {
231	    if (e instanceof InsufficientBalanceError) {
232	      return { error: "Insufficient balance. Top up your wallet first." };
233	    }
234	    throw e;
235	  }
236	
237	  await db.auditLog.create({
238	    data: {
239	      userId: user.id,
240	      action: "gameserver.order",
241	      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
242	    },
243	  });
244	  redirect(`/dashboard/servers/${server.id}`);
245	}
