/**
 * Seed the Business Email mailbox-hosting tiers (EmailPlan rows).
 *
 * Three sensible tiers priced per month:
 *   - Starter  : 1 mailbox  / 10 GB each
 *   - Business : 5 mailboxes / 25 GB each
 *   - Pro      : 25 mailboxes / 50 GB each
 *
 * Idempotent: dedupes by `name` and upserts. Safe to re-run.
 *
 * Run: cd /opt/nxeon && npx tsx prisma/seed-email-plans.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type TierSpec = {
  name: string;
  mailboxes: number;
  storageGB: number;
  priceCents: number;
  termMonths: number;
  sortOrder: number;
};

const TIERS: TierSpec[] = [
  { name: "Starter", mailboxes: 1, storageGB: 10, priceCents: 199, termMonths: 1, sortOrder: 0 },
  { name: "Business", mailboxes: 5, storageGB: 25, priceCents: 799, termMonths: 1, sortOrder: 1 },
  { name: "Pro", mailboxes: 25, storageGB: 50, priceCents: 2499, termMonths: 1, sortOrder: 2 },
];

async function main() {
  let created = 0;
  let updated = 0;

  for (const spec of TIERS) {
    const data = {
      name: spec.name,
      mailboxes: spec.mailboxes,
      storageGB: spec.storageGB,
      priceCents: spec.priceCents,
      termMonths: spec.termMonths,
      active: true,
      sortOrder: spec.sortOrder,
    };

    // No DB unique constraint on name — dedupe manually.
    const existing = await db.emailPlan.findFirst({ where: { name: spec.name } });
    if (existing) {
      await db.emailPlan.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await db.emailPlan.create({ data });
      created++;
    }
    console.log(
      `  ${spec.name.padEnd(10)} ${spec.mailboxes} mailbox(es) · ${spec.storageGB} GB each · ${(spec.priceCents / 100).toFixed(2)}/${spec.termMonths}mo`,
    );
  }

  const total = await db.emailPlan.count();
  console.log(`\nEmailPlans seeded: ${created} created, ${updated} updated. Total in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { addMonths } from "./billing-terms";

/**
 * Business Email — mailbox hosting per registered domain.
 *
 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
 * which debits the wallet, then manages individual `Mailbox` rows under it.
 *
 * IMPORTANT — this is the product + ordering scaffold. Actual mail delivery is a
 * pluggable mail-provider integration that is NOT wired up yet. We therefore do
 * NOT provision real mailboxes or send anything: creating a Mailbox row records
 * intent; the address is marked "provisioning" until the provider integration
 * lands. Nothing here fakes delivery.
 *
 * This module owns:
 *   - orderEmailHosting (customer subscribe)
 *   - addMailbox / removeMailbox (customer mailbox management)
 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
 */

type Result = { error?: string; ok?: boolean };

// ---------- Admin CRUD (billing area) ----------

const planSchema = z.object({
  id: z.string().optional(),
  name: z.string().min(2).max(80),
  mailboxes: z.coerce.number().int().min(1).max(100000),
  storageGB: z.coerce.number().int().min(1).max(100000),
  priceCents: z.coerce.number().int().min(0).max(100000000),
  termMonths: z.coerce.number().int().min(1).max(36),
  sortOrder: z.coerce.number().int().min(0).max(100000),
});

/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
export async function adminSaveEmailPlan(
  prev: Result | undefined,
  formData: FormData,
): Promise<Result> {
  const admin = await requireArea("billing");

  const parsed = planSchema.safeParse({
    id: formData.get("id") || undefined,
    name: formData.get("name"),
    mailboxes: formData.get("mailboxes"),
    storageGB: formData.get("storageGB"),
    priceCents: formData.get("priceCents"),
    termMonths: formData.get("termMonths"),
    sortOrder: formData.get("sortOrder") ?? 0,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
  }
  const d = parsed.data;
  const active = formData.get("active") === "on";

  const data = {
    name: d.name.trim(),
    mailboxes: d.mailboxes,
    storageGB: d.storageGB,
    priceCents: d.priceCents,
    termMonths: d.termMonths,
    active,
    sortOrder: d.sortOrder,
  };

  if (d.id) {
    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
    if (!existing) return { error: "Tier not found." };
    await db.emailPlan.update({ where: { id: d.id }, data });
  } else {
    await db.emailPlan.create({ data });
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: d.id ? "emailplan.update" : "emailplan.create",
      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
    },
  });
  revalidatePath("/admin/email-plans");
  return { ok: true };
}

/** Flip a tier's active flag. */
export async function adminToggleEmailPlan(id: string): Promise<void> {
  const admin = await requireArea("billing");
  const plan = await db.emailPlan.findUnique({ where: { id } });
  if (!plan) return;
  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
  });
  revalidatePath("/admin/email-plans");
}

/** Delete a tier. Refused while subscriptions reference it. */
export async function adminDeleteEmailPlan(id: string): Promise<Result> {
  const admin = await requireArea("billing");
  const plan = await db.emailPlan.findUnique({
    where: { id },
    include: { _count: { select: { subscriptions: true } } },
  });
  if (!plan) return { error: "Tier not found." };
  if (plan._count.subscriptions > 0) {
    return {
      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
    };
  }
  await db.emailPlan.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
  });
  revalidatePath("/admin/email-plans");
  return { ok: true };
}

// ---------- Customer ordering ----------

/**
 * Subscribe one of the caller's registered domains to an email plan. Validates
 * domain ownership + plan availability, then atomically debits the wallet and
 * creates the EmailSubscription with an expiry set from the plan term.
 *
 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
 * provisioned with a mail provider yet — that integration is pending, and the
 * UI surfaces every mailbox as "provisioning" until it lands.
 */
export async function orderEmailHosting(
  domainName: string,
  emailPlanId: string,
): Promise<Result> {
  const user = await requireUser();

  const name = String(domainName ?? "").trim().toLowerCase();
  if (!name) return { error: "Choose a domain." };

  // Ownership check — the domain must be registered to this user.
  const domain = await db.domain.findFirst({ where: { name, userId: user.id } });
  if (!domain) return { error: "That domain isn't in your account." };

  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
  if (!plan || !plan.active) return { error: "That email plan isn't available." };

  // One subscription per domain — refuse a duplicate.
  const dupe = await db.emailSubscription.findFirst({
    where: { userId: user.id, domainName: name, status: { not: "CANCELLED" } },
  });
  if (dupe) return { error: "This domain already has an email subscription." };

  const chargeCents = plan.priceCents;
  if (user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  try {
    await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Business Email: ${plan.name} for ${name}`,
        },
      });
      await tx.emailSubscription.create({
        data: {
          userId: user.id,
          domainName: name,
          emailPlanId: plan.id,
          status: "ACTIVE",
          autoRenew: true,
          expiresAt: addMonths(new Date(), plan.termMonths),
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "emailhosting.order",
      detail: `${name} plan=${plan.name}`,
    },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;

/**
 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
 * quota and address uniqueness within the subscription. No provider call is made
 * (integration pending) — this records the intended mailbox only.
 */
export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({
    where: { id: subscriptionId },
    include: { emailPlan: true, mailboxes: true },
  });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };
  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };

  const local = String(localPart ?? "").trim().toLowerCase();
  if (!localPartRe.test(local) || local.length > 64) {
    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
  }

  const address = `${local}@${sub.domainName}`;

  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
    return {
      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
    };
  }
  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
    return { error: "That address already exists." };
  }

  await db.mailbox.create({
    data: { subscriptionId: sub.id, address },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.add", detail: address },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

/** Remove a mailbox the caller owns (via its subscription). */
export async function removeMailbox(mailboxId: string): Promise<Result> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };

  await db.mailbox.delete({ where: { id: mailbox.id } });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.remove", detail: mailbox.address },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  adminSaveEmailPlan,
