export function EmailPlanForm({ plan, onSaved }: { plan?: EmailPlanRow; onSaved?: () => void }) {
  const [state, action, pending] = useActionState(adminSaveEmailPlan, {} as { error?: string; ok?: boolean });
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state?.ok) {
