/** Expand/collapse wrapper so each existing tier's edit form is tucked away. */
export function EmailPlanEditor({ plan }: { plan: EmailPlanRow }) {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button className="btn-secondary py-1 text-xs" onClick={() => setOpen((o) => !o)}>
        {open ? "Close" : "Edit"}
      </button>
      {open && (
        <div className="mt-3 border-t border-white/[0.06] pt-3">
          <EmailPlanForm plan={plan} onSaved={() => setOpen(false)} />
        </div>
      )}
    </div>
  );
}

export function ToggleEmailPlanButton({ id, active }: { id: string; active: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={active ? "btn-secondary py-1 text-xs" : "btn-primary py-1 text-xs"}
      disabled={pending}
      onClick={() => start(() => adminToggleEmailPlan(id))}
    >
      {active ? "Disable" : "Enable"}
    </button>
  );
}

export function DeleteEmailPlanButton({ id, name }: { id: string; name: string }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        className="btn-danger py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!confirm(`Delete tier "${name}"?`)) return;
          setError(null);
          start(async () => {
            const res = await adminDeleteEmailPlan(id);
            if (res?.error) setError(res.error);
