  const [error, setError] = useState<string | null>(null);
  const [ok, setOk] = useState(false);
  const [pending, start] = useTransition();

  const selected = plans.find((p) => p.id === planId);

  function submit() {
    if (!domain) {
      setError("Choose a domain.");
      return;
    }
    setError(null);
    setOk(false);
    start(async () => {
      const res = await orderEmailHosting(domain, planId);
      if (res?.error) setError(res.error);
      else if (res?.ok) setOk(true);
    });
  }

  return (
    <section>
      <h2 className="mb-3 text-lg font-semibold text-white">Add email hosting</h2>
