  const [error, setError] = useState<string | null>(null);
  return (
    <div className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-white/[0.06] px-3 py-2">
      <div className="flex flex-wrap items-center gap-2">
        <span className="font-mono text-sm text-white">{mailbox.address}</span>
        <Badge tone="amber">Provisioning</Badge>
      </div>
      <div className="flex items-center gap-2">
        {error && <span className="text-xs text-red-400">{error}</span>}
        <button
          className="btn-danger py-1 text-xs"
          disabled={pending}
          onClick={() => {
            if (!confirm(`Remove mailbox ${mailbox.address}?`)) return;
            setError(null);
            start(async () => {
              const res = await removeMailbox(mailbox.id);
              if (res?.error) setError(res.error);
            });
          }}
        >
          Remove
        </button>
      </div>
    </div>
  );
}

function AddMailboxForm({
  subscriptionId,
  domainName,
  atLimit,
}: {
  subscriptionId: string;
  domainName: string;
  atLimit: boolean;
}) {
  const [local, setLocal] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function submit() {
    const v = local.trim();
    if (!v) {
      setError("Enter a mailbox name.");
      return;
    }
    setError(null);
    start(async () => {
      const res = await addMailbox(subscriptionId, v);
      if (res?.error) setError(res.error);
      else if (res?.ok) setLocal("");
    });
  }

  if (atLimit) {
    return (
      <p className="mt-3 text-xs text-amber-400">
        Plan mailbox limit reached. Remove one or upgrade the plan to add more.
      </p>
    );
  }

  return (
    <div className="mt-3">
      {error && <div className="mb-2 text-xs text-red-400">{error}</div>}
      <div className="flex flex-wrap items-end gap-2">
        <div className="min-w-0 flex-1">
          <label className="label">New mailbox</label>
          <div className="flex items-center">
            <input
              className="input rounded-r-none"
              value={local}
              onChange={(e) => setLocal(e.target.value)}
              placeholder="hello"
              onKeyDown={(e) => {
                if (e.key === "Enter") submit();
              }}
            />
            <span className="rounded-r-lg border border-l-0 border-white/10 bg-white/[0.03] px-3 py-2 text-sm text-slate-400">
              @{domainName}
            </span>
          </div>
        </div>
        <button className="btn-primary" onClick={submit} disabled={pending}>
          {pending ? "Adding…" : "Add mailbox"}
        </button>
      </div>
    </div>
  );
}

